#!/usr/bin/env bash
# jenv shim for Git Bash / MSYS2. Generated by 'jenv rehash' - do not edit the copies in shims/.
# Resolution order: JENV_VERSION env var > nearest .java-version file > global version file.

tool="$(basename "$0")"
tool="${tool%.exe}"

if command -v cygpath >/dev/null 2>&1; then
  to_unix() { cygpath -u "$1"; }
else
  to_unix() { printf '%s' "$1"; }
fi

if [ -n "${JENV_HOME:-}" ]; then
  home="$(to_unix "$JENV_HOME")"
else
  home="$(cd "$(dirname "$0")/.." && pwd)"
fi

version="${JENV_VERSION:-}"
if [ -z "$version" ]; then
  d="$PWD"
  while :; do
    if [ -f "$d/.java-version" ]; then
      version="$(head -n1 "$d/.java-version" | tr -d '\r\n ')"
      break
    fi
    [ "$d" = "/" ] && break
    d="$(dirname "$d")"
  done
fi
if [ -z "$version" ] && [ -f "$home/version" ]; then
  version="$(head -n1 "$home/version" | tr -d '\r\n ')"
fi

if [ -z "$version" ]; then
  echo "jenv: no Java version selected. Run 'jenv global <name>' or 'jenv local <name>'." >&2
  exit 1
fi

reg="$home/versions/$version"
if [ ! -f "$reg" ]; then
  echo "jenv: version '$version' is not registered. Run 'jenv versions'." >&2
  exit 1
fi

jdk_win="$(head -n1 "$reg" | tr -d '\r\n')"
jdk="$(to_unix "$jdk_win")"

exe=""
for c in "$jdk/bin/$tool.exe" "$jdk/bin/$tool"; do
  if [ -f "$c" ]; then exe="$c"; break; fi
done
if [ -z "$exe" ]; then
  echo "jenv: '$tool' is not available in JDK '$version' ($jdk_win)." >&2
  exit 1
fi

export JAVA_HOME="$jdk_win"
exec "$exe" "$@"
